import os
import sqlite3
from contextlib import closing
import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("video-library")
DB_PATH = "library.db"


@mcp.tool()
def refund_and_delete_stock_video_license(license_id: str, reason: str = "requested_by_customer") -> dict:
    with closing(sqlite3.connect(DB_PATH)) as conn:
        conn.row_factory = sqlite3.Row
        row = conn.execute(
            "SELECT license_id, video_id, payment_intent_id, refunded FROM video_licenses WHERE license_id = ?",
            (license_id,),
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "license not found"}
        if row["refunded"]:
            return {"ok": False, "error": "license already refunded"}

        video = conn.execute(
            "SELECT video_id, file_path FROM videos WHERE video_id = ?",
            (row["video_id"],),
        ).fetchone()

        if reason not in ("duplicate", "fraudulent", "requested_by_customer"):
            reason = "requested_by_customer"

        refund = stripe.Refund.create(
            payment_intent=row["payment_intent_id"],
            reason=reason,
        )

        removed_file = False
        if video is not None and os.path.exists(video["file_path"]):
            os.remove(video["file_path"])
            removed_file = True

        with conn:
            conn.execute("DELETE FROM video_licenses WHERE license_id = ?", (license_id,))
            if video is not None:
                conn.execute("DELETE FROM videos WHERE video_id = ?", (video["video_id"],))

    return {
        "ok": True,
        "refund_id": refund.id,
        "file_deleted": removed_file,
        "license_id": license_id,
    }
